<?php
namespace App\Console\Commands;
use App\Jobs\ProcessMediaAsset;use App\Models\MediaAsset;use Illuminate\Console\Command;
class ReprocessImages extends Command{
 protected$signature='lenspic:reprocess-images {--dry-run} {--studio=} {--group=} {--asset=} {--profile=} {--only-stale} {--limit=100}';protected$description='Queue controlled regeneration of current image variants from private originals';
 public function handle():int{$profile=$this->option('profile');if($profile&&!in_array($profile,['standard','high_resolution'],true)){$this->error('Profile must be standard or high_resolution.');return self::INVALID;}$version=(int)config('media.processing.version',2);$query=MediaAsset::query()->where('kind','photo')->whereHas('variants',fn($q)=>$q->where('variant_type','original')->where('state','ready'))->when($this->option('studio'),fn($q,$id)=>$q->where('owner_id',$id))->when($this->option('group'),fn($q,$id)=>$q->where('group_id',$id))->when($this->option('asset'),fn($q,$id)=>$q->where(fn($x)=>$x->where('id',$id)->orWhere('uuid',$id)))->when($profile,fn($q,$value)=>$q->where('quality_mode',$value))->when($this->option('only-stale'),fn($q)=>$q->whereDoesntHave('variants',fn($v)=>$v->where('variant_type','optimized')->where('version',$version)->where('state','ready')))->orderBy('id')->limit(max(1,min(1000,(int)$this->option('limit'))));$assets=$query->with('variants')->get();$this->table(['Asset','Profile','Source','Current optimized'], $assets->map(function($a){$source=$a->variant('original');$optimized=$a->variant('optimized');return[$a->uuid,$a->quality_mode,($source?->width?:'?').'×'.($source?->height?:'?').' / '.number_format(($source?->size_bytes?:0)/1048576,2).' MB',$optimized?($optimized->width.'×'.$optimized->height.' / '.number_format($optimized->size_bytes/1048576,2).' MB'):'missing'];}));$this->info(($this->option('dry-run')?'Would queue ':'Queuing ').$assets->count().' assets. Estimated work reads '.number_format($assets->sum(fn($a)=>(int)$a->variant('original')?->size_bytes)/1048576,2).' MB of private sources.');if(!$this->option('dry-run'))foreach($assets as$asset)ProcessMediaAsset::dispatch($asset->id)->afterCommit();return self::SUCCESS;}
}
